<?php
/**
 * Read-only MCP server (Streamable HTTP transport, stateless, JSON responses).
 * Endpoint: https://hussnainahmad.com/mcp/
 * Data comes from data.json in this folder, generated by the Astro build
 * (src/pages/mcp/data.json.ts). No database, no secrets, no write actions.
 */

header('Access-Control-Allow-Origin: *');
header('Access-Control-Allow-Methods: POST, GET, OPTIONS');
header('Access-Control-Allow-Headers: Content-Type, Accept, Mcp-Session-Id, Mcp-Protocol-Version');
header('X-Content-Type-Options: nosniff');

$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';

if ($method === 'OPTIONS') {
    http_response_code(204);
    exit;
}

// This server never pushes messages, so there is no SSE stream to open.
if ($method !== 'POST') {
    http_response_code(405);
    header('Allow: POST, OPTIONS');
    header('Content-Type: application/json');
    echo json_encode([
        'error' => 'This MCP endpoint accepts JSON-RPC over HTTP POST.',
        'server_card' => '/.well-known/mcp/server-card.json',
    ]);
    exit;
}

$dataFile = __DIR__ . '/data.json';
$data = is_readable($dataFile) ? json_decode(file_get_contents($dataFile), true) : null;

function rpc_result($id, $result) {
    return ['jsonrpc' => '2.0', 'id' => $id, 'result' => $result];
}
function rpc_error($id, $code, $message) {
    return ['jsonrpc' => '2.0', 'id' => $id, 'error' => ['code' => $code, 'message' => $message]];
}
function as_text($value) {
    $text = is_string($value) ? $value : json_encode($value, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    return ['content' => [['type' => 'text', 'text' => $text]], 'isError' => false];
}

function handle($msg, $data) {
    if (!is_array($msg) || ($msg['jsonrpc'] ?? null) !== '2.0' || !isset($msg['method'])) {
        return rpc_error($msg['id'] ?? null, -32600, 'Invalid Request');
    }
    $id = $msg['id'] ?? null;
    $isNotification = !array_key_exists('id', $msg);
    $params = $msg['params'] ?? [];

    if ($isNotification) {
        return null; // e.g. notifications/initialized: nothing to send back
    }
    if ($data === null) {
        return rpc_error($id, -32603, 'Server data unavailable');
    }

    switch ($msg['method']) {
        case 'initialize':
            $supported = ['2025-06-18', '2025-03-26', '2024-11-05'];
            $requested = $params['protocolVersion'] ?? '';
            return rpc_result($id, [
                'protocolVersion' => in_array($requested, $supported, true) ? $requested : $supported[0],
                'capabilities' => ['tools' => ['listChanged' => false]],
                'serverInfo' => [
                    'name' => $data['server']['name'],
                    'title' => $data['server']['title'],
                    'version' => $data['server']['version'],
                ],
                'instructions' => $data['server']['instructions'],
            ]);

        case 'ping':
            return rpc_result($id, new stdClass());

        case 'tools/list':
            return rpc_result($id, ['tools' => $data['tools']]);

        case 'tools/call':
            $name = $params['name'] ?? '';
            $args = $params['arguments'] ?? [];
            if ($name === 'get_case_study') {
                $slug = is_array($args) ? ($args['slug'] ?? '') : '';
                if (!isset($data['case_studies'][$slug])) {
                    return rpc_result($id, [
                        'content' => [['type' => 'text', 'text' => 'Unknown case study slug. Use list_case_studies first.']],
                        'isError' => true,
                    ]);
                }
                return rpc_result($id, as_text($data['case_studies'][$slug]));
            }
            if (array_key_exists($name, $data['results'])) {
                return rpc_result($id, as_text($data['results'][$name]));
            }
            return rpc_error($id, -32602, 'Unknown tool: ' . $name);

        default:
            return rpc_error($id, -32601, 'Method not found: ' . $msg['method']);
    }
}

$body = json_decode(file_get_contents('php://input'), true);
if ($body === null) {
    http_response_code(400);
    header('Content-Type: application/json');
    echo json_encode(rpc_error(null, -32700, 'Parse error'));
    exit;
}

// Single message or batch
$isBatch = is_array($body) && array_keys($body) === range(0, count($body) - 1);
$messages = $isBatch ? $body : [$body];
$responses = [];
foreach ($messages as $m) {
    $r = handle($m, $data);
    if ($r !== null) {
        $responses[] = $r;
    }
}

if (count($responses) === 0) {
    http_response_code(202); // only notifications were sent
    exit;
}

header('Content-Type: application/json');
echo json_encode($isBatch ? $responses : $responses[0], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
